  const newbie = () => { const P = A.profile && A.profile.get(); return !advRuns() && !(P && P.stats && P.stats.plays); };
  const clockNow = () => { const d = new Date(); try { const L = (A.LANGS || []).find(l => l.code === A.lang); return d.toLocaleTimeString(L ? L.loc : undefined, { hour: "2-digit", minute: "2-digit" }); } catch (e) { return d.getHours() + ":" + String(d.getMinutes()).padStart(2, "0"); } };
  /* frases que solo pegan en su momento (pickLine se las salta si no): el sabado y el domingo, el boton "Nueva partida" (solo sale con una expedicion
     guardada) y el de "Otra expedicion" (el veredicto del Reto diario no lo tiene: alli es "Jugar el intento" o nada) */
  let curDaily = false;                                                             // la expedicion en curso (o la que acaba de terminar) es del Reto diario
  const ONLY = new Map([[LINES.homeTimeWeekend[3], () => new Date().getDay() === 6], [LINES.homeTimeWeekend[4], () => new Date().getDay() === 0],
    [LINES.homeTempt[8], hasSave], [LINES.runAgainLose[0], () => !curDaily], [LINES.hoverQuit[1], () => !curDaily]]);
  const once = {};                                                                  // guiños que salen como mucho una vez por sesion
