      sign.innerHTML = `<i class="ropes"></i><div class="qx-board"><i></i><b>${A.pick6(SIGN.closed)}</b><span>${A.pick6(SIGN.why)}</span></div>`;
      r.appendChild(sign); setTimeout(() => sign.classList.add("swing"), 900);
