    let on = os, gn = g; try { const L = (A.LANGS || []).find(l => l.code === A.lang), dn = new Intl.DisplayNames([L ? L.loc : A.lang], { type: "language" }); on = dn.of(os); gn = dn.of(g); } catch (e) { /* sin Intl */ }
