    const pool = [stage, stage, "runIdle", "runMeta", "runMeta", "runMeta"]; if (lateHour()) pool.push("homeTimeNight"); if (tGroup(DS.tier) >= 1) pool.push("tierRun" + Math.min(3, tGroup(DS.tier)), "tierRun" + Math.min(3, tGroup(DS.tier)));   // mas cuarta pared, sin trivia mientras piensas
