    if (kind === "roundWin" && ghostR && o.rn === ghostR) { ghostR = 0; const t = say1("ghostBeat", { r: o.rn }); if (t) { sayR(t, { mood: "shock" }); return; } }   // superas la ronda donde caiste
    const big = kind === "roundWin" || kind === "roundFail" || kind === "runWin" || kind === "runLose";
    if (!big && (Date.now() < quietUntil || typing || pend)) return;                    // acaba de decir algo que no conviene pisar, o aun lo esta diciendo (las pequenas no esperan: llegarian tarde)
    if (!big && kind !== "counter" && kind !== "amulet" && (calmNow() || sinceSaid() < BUDGET.smallGap)) return;   // el presupuesto: las pequenas no se amontonan
    if (kind === "amulet") { const t = say1("amuletOn", { p: o.p, c: o.c }); if (t) { sayR(t, { mood: "angry", valid: o.valid, hold: holdFor(t) }); return true; } return; }   // 0.2.5: tu amuleto le estropea un reto (la primera vez de cada uno)
    if (kind === "relic") { const t = say1("relicOn", { p: o.p }); if (t) { sayR(t, { mood: "sly", valid: o.valid, hold: holdFor(t) }); return true; } return; }   // tanda 2: nombra tu reliquia (la primera vez que actua), con presupuesto
