    const p = RX && RX.rara ? 1 : { bull: 1, miss: 1 / 3, timeout: 1 / 3, good: 1 / 3, streak: 1 / 3, counter: 1, roundWin: 1, roundFail: 1, runWin: 1, runLose: 1 }[kind];   // bloque D: 1 de cada 3 (las raras, siempre)
